'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = BigInt(input[0]);
const k = Number(input[1]);
const MOD = 1000000007n;

function gcd(a, b) {
    while (b !== 0n) {
        const t = a % b;
        a = b;
        b = t;
    }
    return a;
}

function modPow(base, exp, mod) {
    base %= mod;
    let result = 1n;
    while (exp > 0n) {
        if (exp & 1n) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1n;
    }
    return result;
}

function isPrime(x) {
    if (x < 2n) return false;

    const smallPrimes = [
        2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n,
        23n, 29n, 31n, 37n
    ];

    for (const p of smallPrimes) {
        if (x % p === 0n) return x === p;
    }

    let d = x - 1n;
    let s = 0;
    while ((d & 1n) === 0n) {
        d >>= 1n;
        s++;
    }

    const witnesses = [
        2n, 325n, 9375n, 28178n,
        450775n, 9780504n, 1795265022n
    ];

    for (let a of witnesses) {
        a %= x;
        if (a === 0n) continue;

        let y = modPow(a, d, x);
        if (y === 1n || y === x - 1n) continue;

        let composite = true;
        for (let r = 1; r < s; r++) {
            y = y * y % x;
            if (y === x - 1n) {
                composite = false;
                break;
            }
        }
        if (composite) return false;
    }

    return true;
}

function pollardRho(x) {
    if (x % 2n === 0n) return 2n;
    if (x % 3n === 0n) return 3n;

    let c = 1n;

    while (true) {
        let a = 2n;
        let b = 2n;
        let d = 1n;

        const f = v => (v * v + c) % x;

        while (d === 1n) {
            a = f(a);
            b = f(f(b));
            d = gcd(a >= b ? a - b : b - a, x);
        }

        if (d !== x) return d;
        c++;
    }
}

const factors = [];

function factorize(x) {
    if (x === 1n) return;
    if (isPrime(x)) {
        factors.push(x);
        return;
    }

    const divisor = pollardRho(x);
    factorize(divisor);
    factorize(x / divisor);
}

factorize(n);
factors.sort((a, b) => a < b ? -1 : a > b ? 1 : 0);

const primePowers = [];
for (const prime of factors) {
    const last = primePowers[primePowers.length - 1];
    if (last && last[0] === prime) {
        last[1]++;
    } else {
        primePowers.push([prime, 1]);
    }
}

let maxExponent = 0;
for (const [, exponent] of primePowers) {
    maxExponent = Math.max(maxExponent, exponent);
}

const inverse = Array(maxExponent + 2).fill(0n);
inverse[1] = 1n;

for (let i = 2; i <= maxExponent + 1; i++) {
    const bi = BigInt(i);
    inverse[i] =
        (MOD - (MOD / bi) * inverse[Number(MOD % bi)] % MOD) % MOD;
}

let answer = 1n;

for (const [prime, exponent] of primePowers) {
    let dp = Array(exponent + 1).fill(0n);
    dp[exponent] = 1n;

    for (let step = 0; step < k; step++) {
        const next = Array(exponent + 1).fill(0n);
        let suffix = 0n;

        for (let e = exponent; e >= 0; e--) {
            suffix = (suffix + dp[e] * inverse[e + 1]) % MOD;
            next[e] = suffix;
        }

        dp = next;
    }

    let expected = 0n;
    let power = 1n;
    const base = prime % MOD;

    for (let e = 0; e <= exponent; e++) {
        expected = (expected + dp[e] * power) % MOD;
        power = power * base % MOD;
    }

    answer = answer * expected % MOD;
}

